 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    whole = Counter(v for row in grid for v in row)
    global_bg = whole.most_common(1)[0][0]

    def dominant(seq):
        v, n = Counter(seq).most_common(1)[0]
        return v, n / len(seq)

    row_info = {r: dominant(grid[r]) for r in range(h)}
    col_info = {c: dominant([grid[r][c] for r in range(h)]) for c in range(w)}
    rows = [r for r, (v, frac) in row_info.items() if v != global_bg and frac >= .72]
    cols = [c for c, (v, frac) in col_info.items() if v != global_bg and frac >= .72]
    if len(rows) < 2 or len(cols) < 2:
        return [[global_bg]]

    row_colors = {r: row_info[r][0] for r in rows}
    col_colors = {c: col_info[c][0] for c in cols}
    separators = set(row_colors.values()) | set(col_colors.values())

    # Only lattice lines that participate in a non-divider colored node delimit
    # the represented figure; plain outer frame lines are discarded.
    active_rows = [r for r in rows if any(grid[r][c] not in separators for c in cols)]
    active_cols = [c for c in cols if any(grid[r][c] not in separators for r in rows)]
    if len(active_rows) < 2 or len(active_cols) < 2:
        return [[global_bg]]

    nonline = [grid[r][c] for r in range(h) for c in range(w)
               if r not in rows and c not in cols]
    cell_bg = Counter(nonline).most_common(1)[0][0] if nonline else global_bg

    out = []
    for r0, r1 in zip(active_rows, active_rows[1:]):
        row = []
        for c0, c1 in zip(active_cols, active_cols[1:]):
            marks = [grid[r][c] for r in (r0, r1) for c in (c0, c1)
                     if grid[r][c] not in separators]
            row.append(Counter(marks).most_common(1)[0][0] if marks else cell_bg)
        out.append(row)

    # Keep just the bounding rectangle containing encoded non-background cells.
    points = [(r, c) for r in range(len(out)) for c in range(len(out[0]))
              if out[r][c] != cell_bg]
    if not points:
        return [[cell_bg]]
    r0 = min(r for r, _ in points); r1 = max(r for r, _ in points)
    c0 = min(c for _, c in points); c1 = max(c for _, c in points)
    return [row[c0:c1 + 1] for row in out[r0:r1 + 1]]
